export const DATA_04: ListeningTest[] = [
  { id: "listening-10", title: "Đề 10", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-10-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-10/part1-1.mp3", script: "1. How will Mary travel to Scotland?\nSpeaker 1: Are you taking the train to Scotland tomorrow, Mary?\nSpeaker 2: No. I’m driving there. It’s cheaper.\nSpeaker 1: Why don’t you go by coach?\nSpeaker 2: Oh no. It takes 7 hours\n2. Where are the shoes?\nSpeaker 1: Mom. Have you seen my brown shoes?\nSpeaker 2: Yes. They’re under the table.\nSpeaker 1: No. They’re not. I left them on the chair this morning. But they’re not there now.\nSpeaker 2: There they are, under the window.\n3. When will the football match start next week?\nSpeaker 1: Does the football match start at 12:15 every week?\nSpeaker 2: No. It was early this week. It usually begins at 2 o’clock.\nSpeaker 1: So it will be the usual time next week.\nSpeaker 2: Yes.\n4. What is the man selling?\nMan: And this? Is the latest model by MacPoint. You'll find it's even quicker at doing your washing up and needs less water. And it's very easy to use, as easy as turning on your shower.\n5. What is the weather forecast for tomorrow?\nWoman: It's been typical spring weather today, sunshine and showers. The next 24 hours should be dry but cloudy. Things look better for the next week, with Monday being a fine sunny day and the following day mild but windy.\n6. Where will the woman go first after work?\nSpeaker 1: Are you and Sarah going straight to the restaurant from work tonight?\nSpeaker 2: Actually I’m leaving work early because I need to do some shopping in the market and I’m going to meet Sarah after that outside the cinema. She doesn’t know where the restaurant is, you see. You’re playing tennis after work, aren’t you?\nSpeaker 1: Yes. So see you at the restaurant.\n7. What can festival visitors see every day?\nThe art centre in London is holding a festival of Irish culture from 4th to 12th of April. An exhibition of paintings is open daily and on some weekday evenings. The theatre has special events including plays and films. At the weekend, concert of Irish music will take place in the town hall\n8. What souvenir will the boy’s mother bring?\nSpeaker 1: What color of T-shirt shall I bring you from New York, Fred?\nSpeaker 2: I prefer black but actually a baseball cap would be a good idea.\nSpeaker 1: What about another model car for your collection. I can get you a New York taxi.\nSpeaker 2: Great. I really like the sports car you bought me last time.", questions: [{ q: "How will Mary travel to Scotland?", options: ["bus", "car", "train", "plane"], answer: 1 }, { q: "Where are the shoes?", options: ["under the window", "under the table", "on the chair", "by the door"], answer: 0 }, { q: "When will the football match start next week?", options: ["11.45 a.m", "12.15 p.m", "02.00 p.m", "04.25 p.m"], answer: 2 }, { q: "What is the man selling?", options: ["A washing machine", "A dishwasher", "A shower", "A water pump"], answer: 1 }, { q: "What is the weather forecast for tomorrow?", options: ["Dry but cloudy", "Sunshine and showers", "Fine and sunny", "Mild but windy"], answer: 0 }, { q: "Where will the woman go first after work?", options: ["the restaurant", "the market", "the cinema", "tennis court"], answer: 1 }, { q: "What can festival visitors see everyday?", options: ["plays", "paintings", "films", "concerts"], answer: 1 }, { q: "What souvenir will the boy’s mother bring?", options: ["a T-shirt", "a baseball cap", "a taxi", "a sports car"], answer: 2 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-10-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-10/part1-2.mp3", script: "Conversation 1:\nPresenter: In today’s programme, David Green has come along to tell us all about Waterside Shopping Center near Northport. Good morning, David.\nDavid: Good morning. Well, I visited Waterside last week and I think it has something for everyone and I would recommend it for a day out. It’s taken three years to build and finally opened three weeks ago, two months later than planned. Firstly, getting there; there are organized coach trips from most towns in the area but they leave early and come home late, so I drove. There are 12,000 free parking spaces, so parking is no problem. You can also get there by train, but the station is 15 minutes from Waterside by bus, and the buses are really crowded so you sometimes have a long wait.\nPresenter: And what about opening times?\nDavid: Well, one thing to remember is that the shops don’t open till 10.00 in the morning except on Saturday when they open at 9.00. So don’t get there too early on a weekday. They close at 8 o’clock every day except Friday when they’re open until 9 pm.\nPresenter: Can you tell us some more about the facilities at the shopping center?\nDavid: Yes, it’s arranged on three levels. You’ll find all your favourites here. In fact if you want to buy a pair of shoes there are 15 different shops to choose from on level one and two. When you run out of money there are seven different banks, but collect your money before you get to the third level as there aren’t any banks up there. On that level, however, there are several restaurants as well as cinema with seven screens. And don’t get lost like I did, go to the information desk on the first level and get a map.\nPresenter: What else can you do at Waterside?\nDavid: Before you go back to your car or the bus – and in fact it might be better to do this before you go shopping and have too much to carry – go and see the lake. Take a walk or have a go at fishing, sailing or wind surfing if you have time. Or you can rest your tired feet and watch the birds and ducks, but you are asked not to feed.\nConversation 2:\nInterviewer: OK, now I understand that the Park is involved in one or two projects at the moment.\nWildlife park representative: That’s right. Since 1994, we’ve been working with various partners to raise money and help co-ordinate something called Project Life Lion. This project involves sending teams to villages which border the Serengeti National Park in East Africa to vaccinate domestic dogs against canine distemper virus (CDV) and rabies. In 1994 over one third of the Serengeti lions died as a result of CDV, which had passed from domestic dogs to the wild animal population. In addition to that, we are currently taking part in the Atlantic Rainforest Project and supporting the Community Conservation Project.\nInterviewer: So you’re obviously concerned about environmental issues.\nWildlife park representative: Yes, the Park continuously monitors its environmental impact. To do that, we have our own independently-written Environmental Management System, which is now being used as a model by other organizations across the UK so that they can establish their own.\nInterviewer: Now, apart from the day-to-day business of visitors to the Park, you also put on events, don’t you?\nWildlife park representative: Yes, the Park is a venue for all manner of corporate events, such as product launches, team-building, special events, barbecues - the list is endless. And we play host to many charity and fund-raising events each year. For them, we are happy to help with discounted tickets and competition prizes.\nInterviewer: Now, tell me about the Center for Television and Radio Training. I gather you’re connected with that.\nWildlife park representative: Yes, it’s our sister’s company. If you’ve always dreamed of being a radio presenter, we offer you the opportunity to take the first steps.\nConversation 3:\nMan: Hello?\nWoman: Hi. It’s Laura Carlton here. We’ve just arrived at the holiday flat, but I can’t get the hot water and heating to work.\nMan: Oh right! That’s easy. Don’t worry. In the upstairs cupboard, you’ll find the water heater. You’ll see three main controls on the left at the bottom of the heater. The first one – the round one on the far left – is the most important one for the heating and hot water. It’s the main control switch. Make sure it’s in the ‘on’ position. The switch itself doesn’t light up, but the little square below will be black if the switch is ‘off’. That’s probably what’s happened – it’s got switched off by mistake. The middle one of these three controls – you’ll see it’s slightly larger than the first one – controls the radiators. If you feel cold while you’re there and need the radiators on, this needs to be turned to maximum. The last of the three controls – the one on the right – is usually on about a number four setting which for the water in the taps is usually quite hot enough. Below the heating controls in the middle is a small round plastic button. If there isn’t enough water in the pipes, sometimes the heater goes out. If this happens you’ll need to press this button to reset the heater. Hold it in for about five seconds and the heater should come on again. Then there’s a little square indicator under the third knob that’s a kind of alarm light. It’ll flash if you need to reset the heater.\nWoman: It sounds complicated\nMan: I’m sure you won’t have any problem with it. There should be some more instructions on the side of the heater. Call me back if you can’t make it work.\nWoman: Okay", questions: [{ q: "What does David say about the shopping center's opening?", options: ["It opened exactly three years after construction began.", "It opened two months later than expected.", "It opened one month earlier than expected.", "It opened three weeks before construction finished."], answer: 1 }, { q: "Why did David choose to drive to Waterside?", options: ["The train journey was too expensive for him.", "The coach would make the visit last most of the day.", "The buses from the station were not running regularly.", "There were no organized coaches from his town."], answer: 1 }, { q: "What should visitors remember about weekday opening times?", options: ["The shops open later than they do on Saturdays.", "The shops close earlier than they do on Fridays.", "The shops open earlier than they do on Fridays.", "The shops remain closed until the afternoon."], answer: 0 }, { q: "What does David recommend doing before buying lots of things?", options: ["Getting cash from one of the banks.", "Checking the center's map carefully.", "Visiting the restaurants on the top level.", "Going to the lake for a walk or activity."], answer: 3 }, { q: "How did domestic dogs contribute to the deaths of many Serengeti lions?", options: ["They competed with lions for food in the park.", "They carried injured lions into nearby villages.", "They passed a serious disease to the wild animals.", "They prevented the lions from receiving vaccines."], answer: 2 }, { q: "Which activity is NOT mentioned as an event held at the park?", options: ["Launching new products", "Organizing family camping trips", "Holding charity fundraising events", "Organizing outdoor barbecues"], answer: 1 }, { q: "What can people do through the park's sister company?", options: ["Learn how to organize corporate events.", "Receive prizes for taking part in competitions.", "Take their first steps towards becoming radio presenters.", "Get discounted tickets for wildlife activities."], answer: 2 }, { q: "Which activity is unrelated to the park's conservation work?", options: ["Protecting lions from diseases", "Supporting rainforest conservation", "Working with local communities", "Offering prizes for charity events"], answer: 3 }, { q: "How is the water heater's control system organized?", options: ["Three main controls are positioned together.", "Two controls operate the heating system.", "Four controls are placed beside the heater.", "Five controls operate different water functions."], answer: 0 }, { q: "What does the man think is probably causing the problem?", options: ["The main control switch is turned off.", "The pipes do not contain enough water.", "The radiator setting is too high.", "The heater needs to cool down first."], answer: 0 }, { q: "Under what circumstances should the small reset button be used?", options: ["When the water from the taps is too hot.", "When the main control has been switched off.", "When there is not enough water in the pipes.", "When the alarm light stops flashing."], answer: 2 }, { q: "What is the woman's reaction to the instructions?", options: ["She is pleased that the problem is already solved.", "She finds them difficult to understand.", "She thinks the instructions are unnecessary.", "She is confident that she can fix it immediately."], answer: 1 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-10-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-10/part1-3.mp3", script: "Talk 1:\nRight, everyone - about the trip to the Jubilee Arts Centre next Wednesday. As you know, we have tickets for the Centre’s two theatres and the concert hall. Those of you with concert tickets will hear piano music by Chopin and Schumann. Those with tickets for the main theatre will see Shakespeare’s Twelfth Night, while people going to the smaller theatre will see The Wild Duck by Ibsen. Although all the theatre and concert tickets have gone, if anyone else would like to join us on the trip I can get tickets for the Arts Centre cinema to see the Australian comedy film, Spider and Rose.\nThe shows begin at half past seven, but we’ll leave early so you can spend time looking around the Arts Centre. The coach will leave here at 3:30 and arrive at the Arts Centre at about a quarter to five. Let me tell you what you can do there.\nThe Centre has a lot of art- lovers. In the Art Gallery there’s an exhibition of the history of Russian ballet. It has dresses and shoes worn by famous dancers and photos of past performances. With your student card, you can get in very cheaply. There are also some interesting free exhibitions. On the ground floor you can see prize- winning paintings from children’s competition, and gold jewellery made by Scottish artists. On the first floor there’s an exhibition of South American photographs, and there’s no charge for that either.\nI know some of you hope to do some shopping. The Centre has a bookshop on the first floor and there’s a souvenir shop by the ticket office. If you’re more interested in clothes and shoes there’s a large shopping centre five minutes’ walk from the Arts Centre.\nYou’ll probably want to eat before the show. The Balcony Restaurant has a menu with a wide range of meals and waiter service, but it is rather expensive. Or there’s the Fountain Restaurant whose special three- course dinner is good value for money. There’s also Charlie’s coffee bar which serves coffee, sandwiches and cakes. You can get fruit juices and ice cream from the cinema kiosk.\nAfter the shows the coach will pick us up at the Bridge Street exit. Everyone should be there by twenty past ten. The two plays will finish at around 10.10 or 10.15. I’m afraid concert- goers will have to wait, as the concert finishes earlier, at ten to ten.\nTalk 2:\nAnnouncer: And now for a few tips of you who are going to go walking this summer. Let’s look first of all at the type of bag that you should take with you. Rod Smith works in a shop that sells camping equipment and he feels he has a bag for every type of walking holiday. Rod, does it really make a difference what type of bag you use?\nRod: Yes, Jill, it certainly does. Bags come in every shape, colour and size now so it makes sense to pick one that is right for your needs. A backpack, for example, could quite rapidly ruin an otherwise good walking holiday if it doesn’t fit your back. In fact the fit is critical but the choice is so large now that it’s difficult to know how to make the right one. So- here are a few things to look for.\nFirst of all size. A bag that holds thirty- five litres and has three outside pockets should be plenty big enough for a day- trip. For a four to five- day walking tour I would recommend a bag that holds seventy litres for a man and fifty to sixty litres for a woman. That’s along with a tent and a sleeping bag. An upright bag- that’s one that closes at the top- is better if you intend to climb a lot of hills.\nWhat about the contents? Well, in order to really avoid the inconvenience of broken containers or crushed clothes, I suggest you go for a bag with a solid bottom. The best ones- but these are probably the most expensive have a leather base that is particularly resistant to wear and tear. A bag that has two compartments inside will allow you to find things more easily and separate out items such as creams that could leak in hot weather. Extra pockets on the outside of the bag are also useful if you want to carry any tools for climbing that are sharp or get dirty when you use them.\nWhen you have to think about carrying your bag. If it’s a backpack, a wide cushioned belt will ease the strain on your back and hops and leave you with more energy for your walking activities. Shoulder straps also help lighten the load and these should be easy to adjust. There are many different types of strap on the market that can be adjusted in various different ways. Try several and compare them. It’s also a good idea to make sure there’s a horizontal bar that goes across your shoulders and stops the straps from falling off.\nWell, if you choose your bag carefully and think about some of the things I’ve mentioned, you shouldn’t waste your money. Finally, make sure there are plenty of air holes in the padded part of your bag that touches your body. These are essential to allow sweat to escape and to make your walking or climbing holiday a comfortable one.\nTalk 3:\nThank you all for coming to my talk this evening. It’s nice to see so many people in the audience. For those of you who don’t know very much about PS Camping let me start by giving some background information about the company.\nThe company started twenty-five years ago. It actually opened as a retail chain selling camping equipment, and then twenty years ago, it bought a small number of campsites in the UK, and began offering camping holidays. The company grew rapidly and has been providing holidays in continental Europe for the last fifteen years.\nIf you book a camping holiday with us, you’ll have a choice of over 300 sites. In Italy we now have some 64 sites that we either own, or have exclusive use of. France is where we have the majority of sites, and we currently have a project to expand into Switzerland. We also have a number of sites in northern Spain, particularly in the mountainous region of Picos de Europa. We’ve upgraded all these Spanish sites, and improved them considerably from their original three-star rating.\nWe believe holidays after superb facilities for the whole family. Parents who want their children to be fully occupied for all or part of the day can take advantage of our children’s activities. These are organized by our well-qualified and enthusiastic staff. Each day kicks off with a sports match, perhaps football, or volleyball, followed by an hour of drama for everyone. This may include singing or dancing, mime or other activities. In the afternoon, there’s a different art activity for each day of the week including a poster competition or modal making. What’s more, our sites are truly child-friendly, and, with this in mind, we operate a no-noise rule in the evenings. Children’s evening activities usually finished at 9:30, or occasionally 10, and from 10:30 holiday-makers are expected to be quiet in the areas where there are tents.\nWe want nothing to go wrong on a PS Camping holiday, but if it does, we also want all customers to be insured. If you haven’t organized an annual insurance policy of your own you’ll need to take out the low-cost cover we offer and we require that you arrange this when you make your holiday reservation.\nThere are many advantages to choosing PS Camping, and to recommending it to others. As a regular customer, you’ll be kept informed of special offers, and your friends can benefit from ten percent off their holidays, or book a luxury tent for the price of a standard one. In return, we’ll send you a thank-you present, which you can choose from a list of high-quality items.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-10", questions: [{ q: "What explains why additional students can only join the group for the cinema?", options: ["Tickets for the other performances have already been sold.", "The theatre performances are restricted to invited students.", "The cinema is the only venue with seats still available.", "Students without tickets cannot enter the concert hall."], answer: 0 }, { q: "What is the main reason for arriving at the Arts Centre so early?", options: ["The group needs extra time to collect their tickets.", "Participants will have time to explore the Centre beforehand.", "The journey is expected to be delayed by evening traffic.", "The performances require everyone to arrive several hours early."], answer: 1 }, { q: "Which exhibition requires visitors to pay unless they have a student card?", options: ["The children's prize-winning paintings", "The Scottish gold jewellery", "The South American photography exhibition", "The Russian ballet exhibition"], answer: 3 }, { q: "What shopping option is available outside the Arts Centre itself?", options: ["A specialist bookshop", "A souvenir shop", "A large clothes and shoe centre", "A market selling local artwork"], answer: 2 }, { q: "Which eating option would best suit someone wanting a relatively inexpensive meal with waiter service?", options: ["Charlie's coffee bar", "The Balcony Restaurant", "The Fountain Restaurant", "The cinema kiosk"], answer: 2 }, { q: "What does Rod's job suggest about his knowledge of walking equipment?", options: ["He organizes walking holidays for experienced climbers.", "He sells camping equipment and advises customers about it.", "He designs specialist bags for professional walkers.", "He trains customers to use equipment safely outdoors."], answer: 1 }, { q: "What type of trip is the 35-litre bag mainly intended for?", options: ["A short day trip", "A four-day trip", "A five-day climbing tour", "A week-long walking holiday"], answer: 0 }, { q: "Why does Rod recommend a bag with two internal compartments?", options: ["They make the bag easier to carry on steep climbs.", "They help protect clothes from being crushed.", "They make it easier to separate potentially leaking items.", "They provide extra space for sharp climbing equipment."], answer: 2 }, { q: "What does Rod recommend doing when choosing shoulder straps?", options: ["Choosing the widest straps available", "Trying different types before making a choice", "Selecting straps made from leather", "Using straps that cannot be adjusted"], answer: 1 }, { q: "What problem are the air holes in the padded section designed to prevent?", options: ["Excessive sweating while carrying the bag", "Damage to the bag's leather base", "Clothing becoming crushed inside the bag", "Sharp tools damaging the outside pockets"], answer: 0 }, { q: "What does the company's history suggest about the development of its business?", options: ["It moved from selling equipment to providing holidays abroad.", "It gradually stopped selling camping equipment in favour of holidays.", "It began by operating European campsites before expanding into the UK.", "It has focused exclusively on campsites since it was established."], answer: 0 }, { q: "Which country currently represents the company's largest campsite network?", options: ["Italy", "Switzerland", "Spain", "France"], answer: 3 }, { q: "Which activity forms a regular starting point for the children's daily programme?", options: ["A sports match", "An hour of drama", "An art competition", "A model-making session"], answer: 0 }, { q: "What does the evening noise policy require campers to do?", options: ["Stop children's activities before 9:30 pm", "Leave the campsite before 10:00 pm", "Keep quiet in tented areas from 10:30 pm", "Avoid all outdoor activities after 9:30 pm"], answer: 2 }, { q: "How does PS Camping reward existing customers who recommend it?", options: ["By giving them a discount on their next holiday", "By letting them choose a thank-you gift", "By upgrading their friends to luxury accommodation", "By providing free insurance for future holidays"], answer: 1 }] } ], },
  ] },
  { id: "listening-11", title: "Đề 11", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-11-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-11/part1-1.mp3", script: "1. Which box of chocolates do they buy?\nSpeaker 1: Which box of chocolate should we get Mom for her birthday?\nSpeaker 2: Those round boxes with the flowers are nice.\nSpeaker 1: Yes. But that square box is cheaper.\nSpeaker 2: But it’s mom’s birthday. Let’s get the big round one. We’ve got enough money.\nSpeaker 1: Ok\n2. When is Wendy’s birthday?\nSpeaker 1: Wendy, You’re 21 on Saturday, aren’t you?\nSpeaker 2: No. My birthday is on May 18th\nSpeaker 1: Well, Saturday isn’t 18th?\nSpeaker 2: No, it’s not. It’s the 16th\n3. How much petrol does the woman want?\nSpeaker 1: Could you put 30 litres of petrol in my car please?\nSpeaker 2: Did you say 13 litres?\nSpeaker 1: No, 30 litres. Filling up please.\n4. What time is the woman’s hair appointment?\nSpeaker 1: I’d like to make an appointment to have my hair cut, please. This Friday or Saturday in the morning if you manage it.\nSpeaker 2: Let me see. We can do Friday. At 10 or 11:30 then on Saturday, there’s 9:30 or 12 o’clock\nSpeaker 1: I’ll take the earlier one on Saturday, please.\n5. Where is the TV guide?\nSpeaker 1: Have you seen the TV guide?\nSpeaker 2: Isn’t it on the top of the television? I had it while I was watching a film last night.\nSpeaker 1: I expect to have left by the chair then. Here it is, under the cushion when nobody can find it. You should put it back in its place by the telephone then we all know where it is\n6. What does the man decide to take Tracy?\nSpeaker 1: I’m going to see Tracy in hospital. But I can’t think of what to take her. People always take flowers.\nSpeaker 2: So she has lots already for sure. I always think it’s nice to have something to read myself but as Tracy got her Walkman with her. What about something to listen to?\nSpeaker 1: What a good idea. It’s better than taking sweets certainly because I know she’s on special diet while she’s in hospital.\n7. Which sport has the man just started?\nSpeaker 1: Hi. How was your holiday?\nSpeaker 2: Great. Really good windsurfing and sailing. You know how much I enjoy them and horse riding. I really want to go again. Now I’ve tried it. And the swimming pool was wonderful, too, much warmer than the one I usually swim in. Holidays are just too short.\n8. What was damaged in the storm?\nSpeaker 1: Was the roof of your house alright after the storm, Anna? I saw a workman there with a ladder today.\nSpeaker 2: I had the roof repaired recently so that wasn’t a problem. The workman was putting some new glass in an upstairs window. I think a branch from a tree broke it when it fell off in the wind. I was quite lucky it didn’t damage my car which was parked right under the tree.", questions: [{ q: "Which box of chocolates do they buy?", options: ["the small round one", "the big round one", "the square one", "the oval one"], answer: 1 }, { q: "When's Wendy's birthday?", options: ["16th May", "18th May", "21st May", "26th May"], answer: 1 }, { q: "How much petrol does the woman want?", options: ["13 litres", "30 litres", "33 litres", "43 litres"], answer: 1 }, { q: "What time is the woman's hair appointment?", options: ["Saturday at 9.30 am", "Saturday at 12.00", "Friday at 10.00", "Friday at 11.30"], answer: 0 }, { q: "Where's the TV guide?", options: ["top of the TV", "by the chair", "under the cushion", "by the telephone"], answer: 2 }, { q: "What does the man decide to take Tracy?", options: ["flowers", "a CD", "sweets", "fruit"], answer: 1 }, { q: "Which sport has the man just started?", options: ["windsurfing", "sailing", "horse-riding", "swimming"], answer: 2 }, { q: "What was damaged in the storm?", options: ["the house roof", "window glass", "a car", "a tree"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-11-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-11/part1-2.mp3", script: "Conversation 1:\nLouise: John\nJohn: Oh Louise. Hi.\nLouise: I’ve just arrived for my singing lesson with Mrs Thompson. What are you doing here?\nJohn: I’ve come for a singing lesson too.\nLouise: Well, if it’s a secret I won’t tell anyone\nJohn: It’s OK, Louise. I’m going to be in a musical show, so everyone will know soon.\nLouise: Really! But can you actually sing then?\nJohn: Well, I was taught to sing at school you know, but now I’m in the show I thought I’d better have a few more lessons.\nLouise: Good idea. What do you think of Mrs Thompson? She’s really strict, isn’t she?\nJohn: She is, but I think if you want to sing properly, then she’s the best teacher. You don’t have to like her to see that she’s really brilliant.\nLouise: Oh, I suppose so, it’s just that she makes me feel so nervous. How did you get chosen for the show?\nJohn: Well, I went to see a few musical shows before Christmas. I don’t know why, because I’d never really liked them before, and I thought I’d like to do that so I tried for a part in the show at The Regent Theatre and got it.\nLouise: Well done ... so have you actually done a show yet?\nJohn: Yes, we’ve done a practice show just for family and friends.\nLouise: So, how did you feel?\nJohn: Well, when we’d finished I wanted to cry because I was so delighted that I’d actually got through it without making any big mistakes.\nLouise: But did people like it?\nJohn: Yes they did, and it was great to have an audience.\nLouise: I would love to be able to sing and have everybody listen and clap\nJohn: It’s quite hard to do a musical show, actually. You have to dance as well as sing. It’s hard work to get it right.\nLouise: Oh, I wouldn’t be keen on that. I’m only a singer really. When does the show open?\nJohn: On the 9th of October. Would you like a couple of free tickets?\nLouise: Oh yes! Thanks!\nConversation 2:\nInterviewer: I’m talking to Jackie Gould, who’s a very proud mother. Both of her daughters – Olivia, aged 12, and Alicia, seven – are currently appearing on the stage of the world-famous London Palladium theatre, in the musical The Sound of Music. Olivia and Alicia survived six auditions to be picked from 1,000 hopefuls for the group of seven children playing the Von Trapp family in the show. So how did it all come about?\nJackie: Well, until last year, the idea of them appearing at the London Palladium would have been unthinkable for our family. Things started to happen when Olivia auditioned for a production of the show Annie at the local theatre. She auditioned for the chorus and, by chance, got the leading role instead.\nInterviewer: That’s a very big role, the leading one in Annie, isn’t it?\nJackie: Yes, for Annie, Olivia had to learn more than 200 lines. She was on stage for most the two-hour show. It was a big script, and I decided that we’d do ten pages a night. After memorizing it, I gave her a random line. She would have to tell me what the next line was. She picked it all up even better than her homework.\nInterviewer: And she did well in the part, presumably?\nJackie: She was great in the part. Everyone was astonished by her performance, including us. She had always been very shy, and she suddenly came out of her shell. We found that she could really sing. A member of the stage management team for the show was taking over a local agency and asked her to sign up. So then she had an agent to represent her and try to get roles for her.\nInterviewer: OK, so what happened next?\nJackie: Well, Olivia was turned down for a part in the musical Mary Poppins. She reached the last ten for the role of Jane Banks. She didn’t get the part and was distraught. But she quickly picked herself up and then we took both children to the Palladium auditions for The Sound of Music.\nConversation 3:\nPaul: Hello, Kira, how are you?\nKira: Fine thanks, Paul, how are you?\nPaul: Well, thanks. It’s good to see you. It must be twelve months since you did our course?\nKira: That’s right. It’s nice to come back and say hello.\nPaul: What course did you enroll in?\nKira: Actually, I went straight into third year Pharmacy. They credited me with two years, which probably made it more difficult for me.\nPaul: On the one hand, you were lucky to be granted credits. Is that why you chose the course?\nKira: Yes. And, as I’d already finished a course in it in my country. I thought it would be easier if I studied something I already knew.\nPaul: I didn’t realise you went into third year. I thought you started in first year. No wonder it was so hard! And what do you think is one of the big differences between studying at a university here and studying in your country?\nKira: Well, I’ve found it very difficult to write assignments, because I wasn’t familiar with that aspect of the system here. The main problem is that the lecturers expect you to be critical. That made me feel really terrible. I thought ‘How can I possibly do it? How can I comment on someone else’s research when they probably spent five years doing it?’ I think a lot of people who come from overseas countries have similar problems. But after a while it became easier for me. People expect you to have problems with the process of reading and writing but, in fact, it is more a question of altering your viewpoint towards academic study.\nPaul: how was the content of the lectures? Was it easy for you?\nKira: I didn’t really have many problems understanding lectures. The content was very similar to what I’d studied before.\nPaul: And what about the lecturers themselves? Are they essentially the same as lecturers in your country?\nKira: Well actually, no. Here, they’re much easier to approach. After every lecture you can go and ask them something you didn’t understand. Or you can make an appointment and talk to them about anything in the course.", questions: [{ q: "Why are John and Louise both at Mrs Thompson's today?", options: ["Louise has come to support John's audition.", "John has come to teach Louise how to sing.", "They have come to watch a musical performance together.", "They have each come for a singing lesson."], answer: 3 }, { q: "What does John think of Mrs Thompson overall?", options: ["He thinks she makes lessons feel stressful for him.", "He thinks she has a wonderful singing voice herself.", "He thinks she's a demanding but excellent teacher.", "He thinks she is easy-going and very relaxed."], answer: 2 }, { q: "What can be inferred about how John's practice show went?", options: ["He felt too nervous to finish the show.", "He got through it without any serious mistakes.", "He forgot several of his lines on stage.", "He performed only for close family members, not friends."], answer: 1 }, { q: "Why wouldn't Louise want to be in a musical show?", options: ["She isn't keen on the dancing it involves.", "She thinks singing lessons are too expensive.", "She doesn't enjoy performing in front of an audience.", "She finds Mrs Thompson too difficult to work with."], answer: 0 }, { q: "How many young people originally hoped to get one of the roles?", options: ["A few hundred children took part in the auditions.", "Around one thousand children took part in the auditions.", "Seven children took part in the auditions overall.", "Six children took part in the final audition round."], answer: 1 }, { q: "What marked the beginning of Olivia's success as a performer?", options: ["She and her sister travelled to London for auditions.", "She was cast in the musical Mary Poppins.", "She won the lead role rather than a chorus part.", "She was chosen for the Von Trapp family in the West End."], answer: 2 }, { q: "How did Olivia practise remembering her lines?", options: ["She read the whole script aloud each evening.", "Her mother tested her by giving random lines.", "She memorised ten pages during each rehearsal.", "Her teachers helped her practise after school."], answer: 1 }, { q: "How did Jackie react to Olivia's performance in Annie?", options: ["She was astonished by how well Olivia did.", "She was unimpressed by the whole performance.", "She discovered that Olivia couldn't really sing well.", "She felt embarrassed by some mistakes Olivia made."], answer: 0 }, { q: "What happened when Kira began studying Pharmacy here?", options: ["She had to restart her Pharmacy course from scratch.", "She returned to her home country after one year.", "She was placed directly into the third year.", "She completed another course before entering Pharmacy."], answer: 2 }, { q: "Why does Kira find the lecture content manageable?", options: ["Because she has grown used to academic writing.", "Because the lecturers explain everything very simply.", "Because she no longer struggles with assignments.", "Because it closely matches what she had already studied."], answer: 3 }, { q: "What does Kira identify as the main difficulty with assignments?", options: ["She finds it hard to understand the lecture content.", "She isn't used to critically evaluating other people's research.", "She feels overwhelmed by the amount of work required.", "She finds the academic system difficult to understand generally."], answer: 1 }, { q: "How does Kira imply lecturers in her home country compare to those here?", options: ["They were far less approachable than lecturers here.", "They liked students asking questions after lectures.", "They were equally easy to approach for extra help.", "They knew much less about their subjects."], answer: 0 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-11-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-11/part1-3.mp3", script: "Talk 1:\nIf you want to take an undergraduate course of study, you require a letter of recommendation from your principle and copies of your school records and exam results. You must of course demonstrate ability to communicate effectively in English. Different majors require different abilities in English. Undergraduate courses in science often require you to do a foundation year before you start the course so that you achieve the requisite knowledge before you begin the courses. Degrees generally last three years, though the first year doesn’t count towards your final marks. Application is always via UCAS, an organization that handles all undergraduate students. Postgraduate application is via direct application to universities. They will require a minimum pass in your degree, certainly above average and as with undergraduate courses require a minimum level in your English ability. Most Master courses take one year, but some take two, so be sure to take this into account when choosing. There are two systems of ranking: for universities overall achievement and for each of their separate departments. Other kinds of information are available, like graduate employment statistics. Generally British universities are generally respected globally and there is an international ranking system that lists all the top universities in the world for you to check where your university places.\nTalk 2:\nMy name is Dan Pearman and I’d like to talk about the work of Pedal Power, a small charity based mainly in the UK. I’ll be giving our contact details at the end, if anyone would like to find out more about how to support us.\nBut first, how the charity began. I got the idea of exporting bicycles to developing countries while I was in Ecuador. I went there in 1993 just after graduating from university. After 3 years of studying, I wanted adventure. I loved travelling, so I decided to join a voluntary organization and was sent to Ecuador to carry out land surveys. The project came to an end after 5 years and when I returned to the UK in 1998, I started planning Pedal Power.\nWhere I lived in Ecuador was a very rural area. My neighbor had the only bicycle in the village, whereas everyone else walked everywhere. My neighbour’s business was unusually successful, and for years I couldn’t understand why. Then I realized having a bike means he could get where he wanted to go without much trouble. Other local carpenters could only accept jobs in a three-kilometre radius, so no matter how skilled they were, they could never do as many jobs as my neighbour.\nAt Pedal Power, we collect second-hand bikes in the UK and send them to some of the poorest regions in the world. When we distribute bikes overseas we don’t give them away for free. We’d like to, but long term that doesn’t really help the local economy. The demand for bikes is enormous which makes them very expensive locally. So we sell them for 5% of the normal price. But in order to continue operating we need to have a constant supply of bikes which we send out every six months.\nOne example of a town that’s received bicycles from Pedal Power is Rivas. It was the first place I sent a full container of bicycles to. Most people there now own a bicycle. The local economy has developed so much, you couldn’t recognize it as the same place. In fact, there are more bikes than on the streets of Amsterdam, if you’ve ever been there.\nBut Pedal Power still needs your help. You may have read about some of our recent problems in the British media. In August 2000 we simple ran out of money. We had containers of bikes ready to send, but no money to pay the bills. It was a terrible situation. We managed to ensure the bikes went out on time, but the other problems carried on for several months.\nTalk 3:\nANNOUNCER: Today’s Health Counsel is presented by Paula Clayburg, who is the chief Counsellor at Liverpool’s famous pain clinic. The Wilton Clinic Paula....\nPAULA CLAYBURG: Do you know what Prince Charles, Steve Ballesteros and Elizabeth Taylor have in common? They all suffer from chronic back pain. In fact, bad backs are one of the most common health problems today, affecting people in all walks of life. The most recent available figures show that about a quarter of a million people are incapacitated with back pain every day.\nAnd many sufferers don’t know the cause of the solution to their problem. The majority of our patients at the clinic tend to be women. They are especially vulnerable because of pregnancy but also because of osteoporosis, which I personally believe to be the major cause of problems for women. I have many women patients who say they have completely given up exercise because the pain makes them so miserable. But of course that starts up a vicious circle. Bed rest, giving up exercise and pain killers are traditional responses to back pain but, although there are many excellent drugs on the market, at our clinic we are beginning to realise the unique benefits of relaxation therapy. Other specialists in the field make a strong case for certain types of exercise, but in our experience they are easily mishandled and can lead to more harm than good.\nNow, let’s look at some of the reasons why back pain is developing into such a unique menace. In general, the body is pretty good at self-repaired. A strain or a blow to a limb, though painful at the time, generally resolves itself. But the body’s response to back injury can be very counter-productive. When pain strikes, we attempt to keep the back as immobile as possible, which makes the muscles tense up. Research shows that they often go into spasm, which causes further twisting of the spine. A vicious circle is underway. The second mistake we often make when stricken with extreme back pain is to go to bed and stay there. Although at the clinic we recognise that a short rest in bed can be helpful...up to two days ... any longer makes our back muscles become weaker and unable to hold up our spine. The pain therefore becomes worse.\nAnother problem is being overweight. Anyone a stone or more over-weight who already has back pain is not doing himself any favor though it won’t actually set it off in the first place, the weight will increase the strain and make things worse. The British diet could be partially to blame for the increase in back pain.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-11", questions: [{ q: "Which item is NOT mentioned as part of an undergraduate application?", options: ["A letter from the applicant's school principal.", "Copies of school records and exam results.", "Evidence of effective English communication.", "A certificate confirming the applicant's health."], answer: 3 }, { q: "Why can the English requirement vary between undergraduate courses?", options: ["Different subjects require different levels of English ability.", "Universities set different requirements for overseas students.", "Applicants' school results determine their language level.", "Students are tested according to their previous experience."], answer: 0 }, { q: "What is the main purpose of a foundation year in some science degrees?", options: ["To provide an alternative route into postgraduate study.", "To give students the knowledge needed before starting the degree.", "To allow students to improve their English before applying.", "To make the first year of the degree count toward final marks."], answer: 1 }, { q: "What does the application process suggest about undergraduate study in the UK?", options: ["Students normally contact each university separately.", "Universities handle all applications independently.", "A central organization handles undergraduate applications.", "Postgraduate and undergraduate applications follow the same system."], answer: 2 }, { q: "Why does the speaker mention both university and department rankings?", options: ["To show that overall rankings are no longer useful.", "To explain that universities can be assessed at different levels.", "To prove that department rankings are more reliable.", "To suggest that employment statistics should be ignored."], answer: 1 }, { q: "What initially led Dan to go to Ecuador?", options: ["He wanted to develop a career in bicycle exports.", "He was looking for work after finishing his university degree.", "He wanted to travel and accepted a voluntary assignment.", "He planned to establish a charity in a developing country."], answer: 2 }, { q: "What did Dan eventually realize about his neighbour's successful business?", options: ["His bicycle allowed him to reach more potential customers.", "His woodworking skills were much better than other craftsmen's.", "His business depended mainly on having better equipment.", "His customers were willing to travel longer distances for him."], answer: 0 }, { q: "Why does Pedal Power charge a small amount for its bicycles?", options: ["To make bicycles affordable while avoiding harm to the local economy.", "To cover the full cost of transporting bicycles overseas.", "To reduce demand in areas where bicycles are already common.", "To ensure that every recipient can afford another bicycle later."], answer: 0 }, { q: "What does the example of Rivas demonstrate about Pedal Power's work?", options: ["The charity has mainly increased bicycle ownership in towns.", "Bicycles can contribute to much wider economic development.", "The charity has made Rivas dependent on overseas donations.", "Most of its successful projects have taken place in Ecuador."], answer: 1 }, { q: "What made the charity's situation in August 2000 particularly difficult?", options: ["It had collected too few bicycles to fill its containers.", "It could not find enough people to distribute the bikes.", "It was forced to cancel shipments because of media criticism.", "It had bicycles ready but lacked money to cover its bills."], answer: 3 }, { q: "Why does Paula consider women particularly vulnerable to back pain?", options: ["They are more likely to avoid exercise when they feel pain.", "Pregnancy and osteoporosis can make them especially susceptible.", "They tend to rely more heavily on traditional pain treatments.", "They are more likely to suffer injuries while exercising."], answer: 1 }, { q: "Why has the clinic become interested in relaxation therapy?", options: ["It has shown particular benefits in their experience.", "It completely replaces the need for medication.", "It prevents patients from developing osteoporosis.", "It is easier to use than all forms of physical exercise."], answer: 0 }, { q: "What does Paula mean by saying that back pain can create a 'vicious circle'?", options: ["Back injuries usually take longer to heal than other injuries.", "People often ignore back pain until it becomes severe.", "Painkillers can temporarily hide symptoms without treating the cause.", "Pain causes tension and inactivity, which can make the pain worse."], answer: 3 }, { q: "Why can staying in bed for too long make back pain worse?", options: ["It prevents the body from responding naturally to pain.", "It causes patients to become more dependent on painkillers.", "It can weaken the muscles that support the spine.", "It puts additional pressure on the injured part of the back."], answer: 2 }, { q: "What point does Paula make about being overweight?", options: ["It can worsen existing back problems without necessarily causing them.", "It is usually the main reason people develop chronic back pain.", "It should be treated before any other cause of back pain.", "It explains why traditional treatments often fail."], answer: 0 }] } ], },
  ] },
  { id: "listening-12", title: "Đề 12", subtitle: "35 câu · 40 phút", durationMin: 40, parts: [
    { n: 1, title: "Part 1", hint: HINTS[1], recordings: [
      { id: "listening-12-p1", label: "Bài nghe Part 1", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-12/part1-1.mp3", script: "Q1: What is the purpose of the message?\nGood afternoon. I'm calling for Julie Gibbs. This is Donald Carson from Doctor Kim's office. I just wanted to confirm your appointment for your annual physical checkup on Friday, June 27 at 3 o'clock. The checkup shouldn't last longer than an hour and a half. Since this is your first visit with Doctor Kim, we'd like you to come to the clinic about 20 minutes early so that we can create a file for you. If you cannot make the appointment, please contact the office and let us know at least a day in advance. Thanks.\nQ2: What is being advertised?\nDo you need a way to relieve your stress? Whether you're looking for a full-time membership or just a day of relaxation, Istanbul Spa has something for you! We have several different services for all your treatment needs. This week, we're offering a full-day service including a full-body massage, aromatherapy and a facial for just one low price. You can also enjoy our hospitality with a healthy and refreshing beverage at our tea lounge.\nQ3: According to the announcement, what will be built near Berryville?\nI am very pleased to announce that city leaders in Berryville have finally approved a proposal to enlarge the airport on Hathor Road. We have given the building contract to Heaton Construction. The new terminal will join our older, existing facilities. Berryville's population has been growing at a rapid rate over the past 15 years, due to the addition of a local university and the recent expansion of several businesses.\nQ4: Who is this announcement probably for?\nThis announcement is for all assembly line employees. Please make sure to check your work schedule as soon as you arrive in the morning to see where you will be working for the day. You will need to sign in by putting your signature in the space by your name. After that, please check the announcement board next to the manager's office for any daily notices. Finally, don't forget to pick up your protective aprons and glasses from the safety area.\nQ5: What is the purpose of the message?\nHi, Rose. This is Dorothy calling from the personnel department. I just wanted to know if you are free to join us for dinner tonight. A few of us will be leaving the office around 5:30 and going to the Thai restaurant. Our new colleague Sophia is coming as well. Anyway, if you'd like to join us, just meet us downstairs in front of the building at about 5. Sophia and I will be taking my car, and you are more than welcome to ride with us. Anyway, I hope to see you later. Bye.\nQ6: What is the purpose of the message?\nHello, Mr. Nakamura. This is Eric Parkman, manager of the personnel department for Linderman Enterprises. We received your resume last week for the accounting position in our shipping department. I was very impressed with your experience and education. I would like to schedule an interview at our office on Friday, April 29 at 10 o'clock. Please give me a call and let me know if that time is good for you. Thank you.\nQ7: What is this message about?\nThank you for calling the Tower Place security department. This office will be closing at 11:00 a.m. Wednesday morning as we relocate to the 10th floor. All security officers will be on duty during this time. The 10th floor office will be open at 9 a.m. Thursday. Please contact the security officer on duty, Roy Williams, at 555-7251 if you need to speak with security personnel after 11 on Wednesday. Thank you.\nQ8: Who is the speaker?\nStaff members of Winton Property Development, welcome to the 8th annual Top Achievers Awards Dinner. When I founded Winton Property Development 13 years ago, I knew that I alone could not make the company the success that it is today. I knew that it would take people like you to help me achieve that goal. The reason why I host this dinner every year is to express my deep appreciation to everyone for working so hard for the continued growth of this company.", questions: [{ q: "What is the purpose of the message?", options: ["To schedule a checkup", "To delay a meeting", "To confirm an appointment", "To request some files"], answer: 2 }, { q: "What is being advertised?", options: ["A city tour", "A spa package", "A hotel", "A hospital"], answer: 1 }, { q: "According to the announcement, what will be built near Berryville?", options: ["A university", "A high school", "A new hospital wing", "An airport terminal"], answer: 3 }, { q: "Who is this announcement probably for?", options: ["Factory employees", "Office managers", "Safety supervisors", "Hotel workers"], answer: 0 }, { q: "What is the purpose of the message?", options: ["To make a reservation at a restaurant", "To ask about a new employee", "To invite a co-worker for dinner", "To offer a ride home"], answer: 2 }, { q: "What is the purpose of the message?", options: ["To make an appointment", "To offer a position", "To cancel an interview", "To confirm receipt of an application"], answer: 0 }, { q: "What is this message about?", options: ["A new security policy", "The business hours", "An office relocation", "A permanent closure"], answer: 2 }, { q: "Who is the speaker?", options: ["A new employee", "The founder", "The chairman of the board", "The personnel director"], answer: 1 }] } ], },
    { n: 2, title: "Part 2", hint: HINTS[2], recordings: [
      { id: "listening-12-p2", label: "Bài nghe Part 2", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-12/part1-2.mp3", script: "Conversation 1 (Q.9-12)\nW: Mr. Stone, this is Susan White from the Speedy Medical Center. I am calling to remind you that you have an appointment with Dr. Johnson tomorrow at 11.\nM: Ah, yes, thank you for reminding me. You know, if you hadn't called, I would've completely forgotten all about it. I've been so busy lately.\nW: Well, we call all of our clients a day before their scheduled appointment. Anyway, please get here 10 minutes before your appointment since there are some forms that you have to fill out. Also, don't forget to bring your insurance information.\nM: Okay, I will remember to bring it with me. Thanks, and I will see you tomorrow then.\nConversation 2 (Q.13-16)\nM: I just read an article in the paper about the medical conference being held in the city this weekend. I'm really looking forward to going there.\nW: Really? I am thinking of going as well. I really want to listen to the talk on that study about soybeans. A lot of my patients have been mentioning it to me lately.\nM: Yes, my patients have been asking me about it, too. Hey, do you want to go together this Saturday?\nW: All right. My in-laws are coming for a visit this Sunday, so Saturday will be perfect.\nConversation 3 (Q.17-20)\nW: I think the customer was quite satisfied with the service we provided.\nM: Yes, I think he was especially happy because he thought the warranty had expired. He managed to get the repair done at no cost.\nW: Well, I am glad that we were able to help a good customer. You know, it's customers like that who will continue to come back to our store.\nM: Yes, I agree with you. I think it's very important that we try to keep all of our customers happy.", questions: [{ q: "Why is Susan calling Mr. Stone?", options: ["To inform him about a change to his appointment.", "To remind him about his upcoming appointment.", "To ask whether he still needs to see the doctor.", "To arrange a new appointment for him."], answer: 1 }, { q: "What can be inferred about Mr. Stone?", options: ["He has been unusually busy recently.", "He often arrives late for appointments.", "He works at the medical center.", "He has decided to see another doctor."], answer: 0 }, { q: "Why should Mr. Stone arrive early?", options: ["He needs time to speak with the doctor.", "He has to provide his medical history.", "He needs to complete some paperwork.", "He must confirm his insurance first."], answer: 2 }, { q: "What does Susan specifically remind Mr. Stone to bring?", options: ["His medical records.", "His insurance information.", "His appointment card.", "His completed forms."], answer: 1 }, { q: "What can be inferred about the two speakers?", options: ["They both organize medical conferences.", "They both work for a newspaper.", "They both study food science.", "They both work in healthcare."], answer: 3 }, { q: "Why is the woman particularly interested in the soybean study?", options: ["She has been researching soybeans herself.", "Her patients have been asking about it.", "Her colleagues recommended the study to her.", "She recently read about it in a journal."], answer: 1 }, { q: "When do the speakers decide to attend the conference?", options: ["This Sunday.", "Next Saturday.", "This Saturday.", "Next Sunday."], answer: 2 }, { q: "Why does the woman prefer Saturday?", options: ["She has family visiting on Sunday.", "She has another conference on Sunday.", "Her husband is working on Sunday.", "The conference ends before Saturday."], answer: 0 }, { q: "What are the speakers mainly discussing?", options: ["A problem with the store's warranty policy.", "A customer who recently received assistance.", "A new repair service offered by the store.", "A complaint about the quality of a product."], answer: 1 }, { q: "Why was the customer especially pleased with the service?", options: ["He received a replacement product for free.", "He was given a longer warranty period.", "He got his repair without having to pay.", "He received the repair sooner than expected."], answer: 2 }, { q: "Why does the woman consider the customer valuable to the store?", options: ["He is likely to continue using the store.", "He regularly recommends the store to others.", "He rarely asks for help with products.", "He usually pays more than other customers."], answer: 0 }, { q: "What do the speakers agree is important for the store?", options: ["Reducing the cost of repairs.", "Offering longer warranty periods.", "Providing faster service than competitors.", "Keeping loyal customers satisfied."], answer: 3 }] } ], },
    { n: 3, title: "Part 3", hint: HINTS[3], recordings: [
      { id: "listening-12-p3", label: "Bài nghe Part 3", audio: "https://cdn.thanhnamnguyen.dev/vstep/audio/listening/listening-12/part1-3.mp3", script: "Conversation 1 (Q.21-25)\nW: Hi, there. I was looking for information about becoming a political science major.\nM: Sure. We have some brochures right here.\nW: Thanks, but could I ask you a few questions?\nM: No problem. Fire away.\nW: Are there many requirements for Political Science?\nM: Uh, not really ... Just you must take Political Science 1 and 2, a general history class, and a writing seminar.\nW: I thought you had to take economics, too.\nM: Not for the general Political Science program. But there are a couple of specialized programs that have additional requirements.\nW: Oh, really? What are they?\nM: Well, there is the International Relations program. It is more interdisciplinary, so it requires economics and a second history credit; the two history credits have to be in different regions. There is also the honors Political Science program. To get into that, you need to take the same economics class as the International Relations program, and a special Political Science seminar. And you need to maintain over a \"B\" average in all those required courses.\nW: Wow, that sounds difficult.\nM: Yeah, not many people are qualified for the honors program. That's why it's considered more prestigious, I guess.\nW: Is that all?\nM: No. You also have to complete this form, listing all the Political Science and related credits you have already taken or plan to take, and get the department chair to sign off on it.\nW: Uggh. This is really a lot of work.\nM: Yeah, but everyone has to do it. It's not different from any other majors; the department wants to know that you've thought about your major carefully and thoroughly, and that all the students are being realistic in their expectations.\nConversation 2 (Q.26-30)\nM: Hey, Clara. Got a minute?\nW: Oh, hi, Will. Sure, I've got plenty of time. What's the matter?\nM: Did you see the poster saying that our debate club meeting tonight had been moved?\nW: Oh yes, you didn't get the email?\nM: My computer hasn't been working these few days, so I can't get access to my mailbox. Anyway, why has it been moved?\nW: That whole wing of the Student Union building is getting repainted today, so it's off-limits until the paint dries, vented properly and the workers clean everything up.\nM: It's about time. The club offices in the student building have been looking rundown for quite a while now. A new paint-job would do them a world of good.\nW: And the rooms are going to be repainted in a lighter color, too. That old paint was too dark and depressing.\nM: A lighter color would help everything look bigger, too. Our debate club could use that.\nW: Yeah, but we need more than just light paint. We've grown too big for that little room; we really need to move into a bigger place.\nM: Any chance of that happening?\nW: Not that I know of. Except for tonight, that is, just for this once, we'll be meeting downstairs in Turner Auditorium.\nM: That place is huge, way too big for us.\nW: I know, but it was the only place available tonight. And it was either there or else cancel the meeting altogether.\nM: I guess it's better than canceling. Although, to be honest, I could use another week to prepare for my speech, I've been really busy with my classes lately.\nConversation 3 (Q.31-35)\nScience fiction is very popular these days - in books, in movies, and on TV. Unfortunately, popular science fiction is often a lot more \"fiction\" and not so much \"science.\" One of the most common problems is science fiction’s fascination with faster-than-light travel. We know that is impossible, as it violates Einstein’s basic theory of space and time, but on Star Trek and other science fiction shows, spaceships jump from star to star and galaxy to galaxy like you or I might want to drive to another city. In truth, the closest star to Earth, Proxima Centauri, is over three light years away. That means traveling at the speed of light, the fastest speed anyone theoretically could travel, it would take three years to make it to our nearest neighbor. Other stars and galaxies are routinely thousands and millions of light years away, making intergalactic travel an impossibility. Even if we grant that such space travel somehow was possible, there is no shortage of other errors in popular science fiction. In Star Wars and other films, spaceships swoop across the screen, with their ... uh ... their engines emitting a great roar. However, since space is a void, sound waves cannot travel. There is no sound in space; it is utterly silent. Gravity is another mystery in these films. Gravity depends mostly on mass. Spaceships are tiny compared to the mass of earth. In space there should be practically no gravity. And yet people in science fiction routinely walk around on their spaceships in space as comfortably as they would on earth. That said, there have been a few, scarce films that bothered to portray the science of space flight somewhat realistically. In 2001: A Space Odyssey, the ship must rotate to create artificial gravity. Outside the spaceship, there is total silence. And the voyage from Earth to Jupiter takes many months. But such films are the exception, not the rule. While science fiction may be enjoyable, you should look elsewhere to learn about science.\nNguồn: https://vstepowl.com/listening/de-thi/?exam=listening-12", questions: [{ q: "What is the woman mainly trying to find out?", options: ["Whether her existing credits can be transferred.", "Whether she meets the honors program requirements.", "What she needs to study for a Political Science major.", "How difficult the Political Science courses are."], answer: 2 }, { q: "What misunderstanding does the woman have about the general program?", options: ["She thinks a history course is optional.", "She thinks an economics course is required.", "She thinks a writing seminar is unnecessary.", "She thinks Political Science 1 is not required."], answer: 1 }, { q: "What makes the history requirement for International Relations more demanding?", options: ["Students must study two different historical regions.", "Students must replace history with an economics course.", "Students must take history at a more advanced level.", "Students must complete two additional history seminars."], answer: 0 }, { q: "Why does the man associate the honors program with greater prestige?", options: ["It offers more specialized courses than other programs.", "It attracts students from several different departments.", "Its requirements are difficult for many students to satisfy.", "Its students do not need to complete the usual requirements."], answer: 2 }, { q: "What is the main purpose of the department's detailed registration process?", options: ["To make Political Science harder to enter than other majors.", "To compare students' academic records with other departments.", "To determine which students qualify for the honors program.", "To ensure students have planned their studies realistically."], answer: 3 }, { q: "Why will the debate club meet in Turner Auditorium tonight?", options: ["Its usual room is unavailable because of repainting.", "The club expects an unusually large audience.", "The club has permanently moved to a larger venue.", "Its usual room is being used by another organization."], answer: 0 }, { q: "Why did the man miss the email about the meeting change?", options: ["He had not checked his email recently.", "His computer was not functioning properly.", "He had been away from the university.", "The club had sent the message to the wrong address."], answer: 1 }, { q: "What is the repainting expected to improve besides the appearance of the building?", options: ["The amount of space available for club activities.", "The number of organizations using the building.", "The condition of the club's office equipment.", "The atmosphere of the rooms used by students."], answer: 3 }, { q: "What problem will remain after the repainting is completed?", options: ["The club will still need a larger meeting room.", "The building will still require further repairs.", "The club will still lack enough members.", "The rooms will still have poor lighting."], answer: 0 }, { q: "What does the man's final comment suggest about his speech?", options: ["He has decided not to give the speech tonight.", "He feels he needs more time to prepare it.", "He wants to change the subject of his speech.", "He is confident that the speech is already finished."], answer: 1 }, { q: "What is the main purpose of the professor's talk?", options: ["To explain why science fiction has become popular.", "To compare different approaches to making science fiction.", "To identify scientific inaccuracies in popular science fiction.", "To introduce several successful science fiction films."], answer: 2 }, { q: "Why does the professor use Proxima Centauri as an example?", options: ["To show how quickly modern spaceships can travel.", "To explain why galaxies are difficult to observe.", "To demonstrate how far even the nearest star is.", "To prove that light travels differently between stars."], answer: 2 }, { q: "Why does the professor criticize the sound effects in space films?", options: ["Spacecraft engines would actually be much louder.", "Sound cannot travel through the vacuum of space.", "Astronauts would hear only sounds inside their ships.", "Modern spacecraft use completely different engines."], answer: 1 }, { q: "What does 2001: A Space Odyssey demonstrate that most science fiction films do not?", options: ["It shows that faster-than-light travel is achievable.", "It focuses mainly on the dangers of artificial gravity.", "It avoids showing long journeys between distant planets.", "It presents space travel using more realistic science."], answer: 3 }, { q: "What conclusion does the professor draw about using science fiction to learn science?", options: ["Only older science fiction can provide reliable information.", "Popular films are useful if viewers understand their limitations.", "Science fiction is generally entertaining but unreliable as a science source.", "Realistic science fiction can replace more traditional science materials."], answer: 2 }] } ], },
  ] },
];
